    // endregion

    // region ELEVENLABS (API-ключ)

    /**
     * Озвучка ElevenLabs. Запрос уходит с ОДНИМ voice_id, поэтому роль
     * выражается самим голосом: голос из словаря ролей, иначе голос из
     * настроек, иначе дефолт по полу ([elevenVoiceId]). Раньше пол и слот
     * терялись, и весь текст звучал одним и тем же голосом.
     */
    private fun speakElevenLabs(
        context: Context,
        text: String,
        roleVoice: String? = null,
        gender: String? = null,
    ) {
        val p = prefs()
        val apiKey = p.elevenApiKey().get()
        if (apiKey.isBlank()) {
            // Ключа нет — честный фолбэк на бесплатную веб-озвучку
            speakGoogleWeb(context, text)
            return
        }
        val voiceId = elevenVoiceId(roleVoice, gender)
        currentJob = scope.launch {
            setSpeaking(true)
            try {
                val conn = URL("https://api.elevenlabs.io/v1/text-to-speech/$voiceId")
                    .openConnection() as HttpURLConnection
                conn.requestMethod = "POST"
                conn.doOutput = true
                conn.connectTimeout = 20_000
                conn.readTimeout = 60_000
                conn.setRequestProperty("xi-api-key", apiKey)
                conn.setRequestProperty("Content-Type", "application/json")
                conn.setRequestProperty("Accept", "audio/mpeg")
                val body = """{"text":${jsonQuote(text)},"model_id":"eleven_multilingual_v2"}"""
                conn.outputStream.use { it.write(body.toByteArray()) }
                if (conn.responseCode in 200..299) {
                    val file = File(context.cacheDir, "tts_eleven.mp3")
                    conn.inputStream.use { input -> file.outputStream().use { input.copyTo(it) } }
                    playFileBlocking(file)
                } else {
                    logcat(LogPriority.WARN) { "ElevenLabs HTTP ${conn.responseCode}" }
                    speakGoogleWebInline(context, text)
                }
                conn.disconnect()
            } catch (e: Exception) {
                logcat(LogPriority.WARN, e) { "ElevenLabs TTS failed" }
                speakGoogleWebInline(context, text)
            } finally {
                setSpeaking(false)
            }
        }
    }

    /**
     * voice_id для реплики: голос роли → голос из настроек → дефолт по полу.
     *
     * Питч и темп сюда НЕ передаются: запрос ElevenLabs собирается только из
     * text/model_id/voice_id, и выдумывать параметры просодии, которых этот
     * вызов не отправляет, бессмысленно — они бы просто потерялись.
     */
    private fun elevenVoiceId(roleVoice: String?, gender: String?): String {
        roleVoice?.let { spec ->
            val id = parseVoiceSpec(spec).second.ifBlank { spec }
            if (ELEVEN_VOICE_ID.matches(id)) return id
        }
        val saved = runCatching { prefs().elevenVoiceId().get() }.getOrDefault("").trim()
        if (saved.isNotBlank()) return saved
        return if (gender == "male") ELEVEN_MALE_VOICE else ELEVEN_FEMALE_VOICE
    }

    /** Фолбэк внутри уже запущенной корутины. */
    private suspend fun speakGoogleWebInline(context: Context, text: String) {
        val lang = prefs().ttsWebLanguage().get().ifBlank { "ru" }
        for (chunk in splitForWeb(text, 180)) {
            val url = "https://translate.google.com/translate_tts" +
                "?ie=UTF-8&client=tw-ob&tl=" + lang +
                "&q=" + URLEncoder.encode(chunk, "UTF-8")
            val file = downloadToCache(context, url) ?: continue
            playFileBlocking(file)
        }
    }

    // endregion

    // region helpers

    /**
     * Реальный список голосов аккаунта ElevenLabs (GET /v1/voices по ключу).
     * Возвращает пары (voice_id, имя + категория). Пустой список при ошибке
     * или отсутствии ключа — никаких фейковых данных.
     */
    suspend fun fetchElevenVoices(apiKey: String): List<Pair<String, String>> = withContext(Dispatchers.IO) {
        if (apiKey.isBlank()) return@withContext emptyList()
        runCatching {
            val conn = URL("https://api.elevenlabs.io/v1/voices").openConnection() as HttpURLConnection
            conn.connectTimeout = 15_000
            conn.readTimeout = 30_000
            conn.setRequestProperty("xi-api-key", apiKey)
            if (conn.responseCode !in 200..299) {
                logcat(LogPriority.WARN) { "ElevenLabs voices HTTP ${conn.responseCode}" }
                conn.disconnect()
                return@runCatching emptyList()
            }
            val body = conn.inputStream.bufferedReader().readText()
            conn.disconnect()
            val arr = org.json.JSONObject(body).optJSONArray("voices") ?: return@runCatching emptyList()
            buildList {
                for (i in 0 until arr.length()) {
                    val v = arr.optJSONObject(i) ?: continue
                    val id = v.optString("voice_id")
                    if (id.isBlank()) continue
                    val name = v.optString("name").ifBlank { id }
                    val labels = v.optJSONObject("labels")
                    val extra = buildList {
                        labels?.optString("gender")?.takeIf { it.isNotBlank() }?.let(::add)
                        labels?.optString("accent")?.takeIf { it.isNotBlank() }?.let(::add)
                        v.optString("category").takeIf { it.isNotBlank() }?.let(::add)
                    }.joinToString(", ")
                    add(id to if (extra.isBlank()) name else "$name ($extra)")
                }
            }
        }.getOrElse {
            logcat(LogPriority.WARN, it) { "ElevenLabs voices fetch failed" }
            emptyList()
        }
    }

    private fun jsonQuote(s: String): String {
        val sb = StringBuilder("\"")
        for (c in s) {
            when (c) {
                '"' -> sb.append("\\\"")
                '\\' -> sb.append("\\\\")
                '\n' -> sb.append("\\n")
                '\r' -> sb.append("\\r")
                '\t' -> sb.append("\\t")
                else -> sb.append(c)
            }
        }
        return sb.append('"').toString()
    }

    /** Делит текст на предложения по .!?…; куски без знаков — по 200 симв. */
    fun splitSentences(text: String): List<String> {
        val result = mutableListOf<String>()
        val sb = StringBuilder()
        for (ch in text) {
            sb.append(ch)
            if (ch == '.' || ch == '!' || ch == '?' || ch == '…' || ch == '‼' || ch == '⁇') {
                if (sb.isNotBlank()) result += sb.toString()
                sb.clear()
            } else if (sb.length >= 200 && ch == ' ') {
                result += sb.toString()
                sb.clear()
            }
        }
        if (sb.isNotBlank()) result += sb.toString()

        // Страховка: TextToSpeech.speak() бросает IllegalArgumentException,
        // если строка длиннее getMaxSpeechInputLength() (обычно 4000).
        // Текст без знаков препинания и без пробелов не резался ничем выше.
        return result.flatMap { it.chunked(HARD_UTTERANCE_LIMIT) }
    }

    private fun splitForWeb(text: String, max: Int): List<String> {
        if (text.length <= max) return listOf(text)
        val parts = mutableListOf<String>()
        var rest = text.trim()
        while (rest.isNotEmpty()) {
            if (rest.length <= max) { parts += rest; break }
            var cut = rest.lastIndexOfAny(charArrayOf('.', '!', '?', '…', ';'), max)
            if (cut < max / 2) cut = rest.lastIndexOf(' ', max)
            if (cut < max / 2) cut = max
            parts += rest.substring(0, cut + 1).trim()
            rest = rest.substring(cut + 1).trim()
        }
        return parts.filter { it.isNotBlank() }
    }

    private fun downloadToCache(context: Context, url: String): File? {
        return try {
            val conn = URL(url).openConnection() as HttpURLConnection
            conn.connectTimeout = 15_000
            conn.readTimeout = 30_000
            // Без браузерного UA endpoint отдаёт 403
            conn.setRequestProperty(
                "User-Agent",
                "Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120 Mobile Safari/537.36",
            )
            if (conn.responseCode !in 200..299) {
                conn.disconnect()
                return null
            }
            val file = File(context.cacheDir, "tts_web_${System.nanoTime()}.mp3")
            conn.inputStream.use { input -> file.outputStream().use { input.copyTo(it) } }
            conn.disconnect()
            file
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "TTS download failed" }
            null
        }
    }

    private suspend fun playFileBlocking(
        file: File,
        deleteAfterPlayback: Boolean = true,
    ) {
        withContext(Dispatchers.IO) {
            suspendCancellableCoroutine { cont ->
                val mp = MediaPlayer()
                mediaPlayer = mp
                try {
                    mp.setDataSource(file.absolutePath)
                    mp.setOnCompletionListener {
                        runCatching { mp.release() }
                        if (deleteAfterPlayback) file.delete()
                        if (cont.isActive) cont.resume(Unit)
                    }
                    mp.setOnErrorListener { _, _, _ ->
                        runCatching { mp.release() }
                        if (deleteAfterPlayback) file.delete()
                        if (cont.isActive) cont.resume(Unit)
                        true
                    }
                    mp.prepare()
                    mp.start()
                    cont.invokeOnCancellation {
                        runCatching { mp.stop(); mp.release() }
                        if (deleteAfterPlayback) file.delete()
                    }
                } catch (e: Exception) {
                    runCatching { mp.release() }
                    if (deleteAfterPlayback) file.delete()
                    if (cont.isActive) cont.resume(Unit)
                }
            }
        }
    }

    // endregion

    // region Таблицы голосов сетевых движков

    /**
     * Настоящие женские/мужские голоса Edge по языкам. Слот персонажа сдвигает
     * выбор по списку, поэтому две женщины (или два мужчины) в одной сцене
     * говорят разными голосами — ровно то, чего не хватало авточтению.
     * Имена взяты из публичного каталога edge-tts; неизвестный серверу голос
     * даёт пустой ответ, и [speakEdgeTts] откатывается на системный.
     */
    private val EDGE_GENDER_VOICES: Map<String, Map<String, List<String>>> = mapOf(
        "ru" to mapOf(
            "female" to listOf("ru-RU-SvetlanaNeural", "ru-RU-DariyaNeural", "ru-RU-XeniaNeural"),
            "male" to listOf("ru-RU-DmitryNeural", "ru-RU-MaximNeural"),
        ),
        "uk" to mapOf(
            "female" to listOf("uk-UA-PolinaNeural"),
            "male" to listOf("uk-UA-VolodymyrNeural"),
        ),
        "en" to mapOf(
            "female" to listOf("en-US-AriaNeural", "en-US-JennyNeural", "en-US-MichelleNeural"),
            "male" to listOf("en-US-GuyNeural", "en-US-EricNeural", "en-US-ChristopherNeural"),
        ),
    )

    /**
     * Мультиязычные голоса Edge — запасной вариант для языка, на который в
     * таблице выше голоса нет: они понимают и русский, и восточноазиатские
     * языки, поэтому озвучка не превращается в «все голоса сразу».
     */
    private val EDGE_MULTILINGUAL_VOICES = mapOf(
        "female" to "en-US-AvaMultilingualNeural",
        "male" to "en-US-AndrewMultilingualNeural",
    )

    /** Голоса по умолчанию ElevenLabs из стартовой библиотеки аккаунта. */
    private const val ELEVEN_FEMALE_VOICE = "21m00Tcm4TlvDq8ikWAM" // Rachel
    private const val ELEVEN_MALE_VOICE = "VR6AewLTIGv4JNBf1nQv" // Arnold

    /**
     * id моделей удалённого сервера: ровно эти значения он понимает (плюс
     * «female»/«male»/«auto»). Список берём из каталога голосов приложения, а
     * не выдумываем, иначе сервер тихо подставит «irina» всем.
     */
    private val REMOTE_SERVER_VOICE_IDS: Set<String> =
        eu.kanade.tachiyomi.data.voice.VoicePlugins.REMOTE_VOICE_CATALOG_IDS
            .map { it.lowercase(Locale.US) }
            .toSet()

    /** voice_id ElevenLabs: буквы и цифры без разделителей. */
    private val ELEVEN_VOICE_ID = Regex("""[A-Za-z0-9]{16,32}""")

    // endregion
}

