            id = SoundId.CRY,
        ),
        Sound(
            spoken = "А-а-а...",
            pitch = 0.92f,
            rate = 0.85f,
            pauseMs = 320,
            words = listOf(
                "стонет от боли", "стон", "стонет", "хнычет", "хнычеть",
                "ныть", "поскуливает", "скулит",
