            id = SoundId.MOAN,
        ),
        Sound(
            spoken = "А-а-а!",
            pitch = 1.05f,
            rate = 0.95f,
            pauseMs = 240,
            words = listOf(
                "вдох", "вдыхает", "задыхается", "хватает воздух",
                "не хватает воздуха", "дышит часто", "задыхаясь",
            ),
            id = SoundId.GASP,
        ),
        Sound(
            spoken = "А-а-а...",
            pitch = 0.86f,
            rate = 0.78f,
            pauseMs = 360,
            words = listOf(
                "вздох", "вздыхает", "вздохнув", "выдох", "выдыхает",
            ),
            id = SoundId.SIGH,
        ),
        Sound(
            spoken = "Ха-ха-ха!",
            pitch = 1.12f,
            rate = 1.12f,
            pauseMs = 260,
            words = listOf(
                "смеется", "смеётся", "смех", "хохочет", "хихикает",
                "усмехается", "смешок",
            ),
            id = SoundId.LAUGH,
