        Sound(
            spoken = "Кхм... Кхм!",
            pitch = 0.94f,
            rate = 0.9f,
            pauseMs = 300,
            words = listOf("кашель", "кашляет", "кашлянул", "кашлянуть", "кашлит"),
            id = SoundId.COUGH,
        ),
    )

    // Тише и медленнее — шёпот. Бег, усталость и слабость меняют темп, и
    // порядок снова важен: «задыхаясь» не должно превращаться в шёпот.
    private val STATES = listOf(
        State(
            1.0f, 0.72f,
            listOf("шёпот", "шепот", "шёпотом", "шепчет", "шепчетом", "тихо говорит", "потихоньку"),
        ),
        State(
            1.02f, 1.18f,
            listOf("бежит", "бегом", "на бегу", "бегущий", "на бегущих", "спешит", "торопится", "в бегах"),
        ),
        State(
            0.92f, 0.86f,
            listOf(
                "устал", "устала", "усталость", "тяжело дышит", "выдохшийся",
                "выдохлась", "истощен", "истощён", "без сил", "сил нет",
            ),
        ),
        State(
            0.88f, 0.80f,
            listOf(
                "слабость", "вялость", "обессилел", "обессилела", "слабый голосом",
                "едва говорит", "хрипло", "сипло",
            ),
        ),
        State(
            0.95f, 0.88f,
            listOf("боль", "болит", "рана", "ранен", "ранена", "испытывает боль"),
        ),
        State(
            0.90f, 1.05f,
            listOf("испуг", "боится", "боюсь", "страх", "трусит", "дрожит", "боязливо"),
        ),
        State(
            1.12f, 1.12f,
            listOf("злость", "злится", "ярость", "сердит", "взбешён", "взбешен", "разозлён", "разозлен"),
        ),
        State(
            1.14f, 1.04f,
            listOf(
                "удивлён", "удивлен", "удивление", "изумлён", "изумлен",
                "шок", "потрясён", "потрясен", "разился",
            ),
        ),
    )

    /**
     * Ремарки в скобках: `(вздох)`, `[ааа]`, `*шёпотом*`, а также курсив и
     * кавычки. Закрывающая скобка экранирована — без экрана ICU-движок
     * части Android падает прямо на разборе шаблона (см. предупреждение
     * в [SpeechMarkup]).
     */
    // Внутренняя часть ремарки допускает `*`: разметка `(*шёпотом*)` и `(шёпотом)`
    // должны разбираться одинаково. Запрещены только закрывающие скобки — иначе
    // группа «съест» конец ремарки. Закрывающая часть — целая серия: у `(*шёпотом*)`
    // их две (`*` и `)`), иначе хвост утекал бы в произносимый текст.
    private val CUE_SPAN = Regex("""[(\[*]\s*([^()\[\]\{\}]{1,60}?)\s*[\)\]\*]+""")

    /**
     * Кандидат в междометие: короткая «слово-сгусток» из букв и дефисов,
     * стоящая сама по себе. Дальше решает белый список, а не сам шаблон.
     *
     * Так сделано намеренно. Если разрешить «любую последовательность из
     * а, у, о, м, х», под неё попадут обычные слова: «еху», «уху», «аму»,
     * «уа», «хам», «ом». Список явный, поэтому «хам» останется словом.
     */
    private val CANDIDATE = Regex("""(?<![\p{L}\p{N}])([\p{L}\-]{1,12})(?![\p{L}\p{N}])""")

    /**
     * Белый список междометий. Повторы букв и дефисы значимы: «а» — это
     * удивление, «аа» — попытка закричать, «ааа» — уже крик, «а-а-а» —
     * то же, но тянутое.
     */
    private val INTERJECTIONS: Set<String> = setOf(
        // удивление, короткое «а» и его вытянутые варианты
        "а", "аа", "ааа", "аааа", "ааааа", "аааааа",
        "а-а", "а-а-а", "а-а-а-а", "а-а-а-а-а",
        "а-а-а-а-а", "а-ах", "а-а-а-х", "аа-а", "а-а-ах", "аах", "а-у-а",
        // вдох / выдох / хрип
        "ах", "аха", "ахх", "ааах", "ааа-а", "ух", "уха", "уух", "уах", "ухх",
        "ох", "оха", "о-о", "о-о-о", "оах", "охх",
        // тяжёлое дыхание, усталость
        "у", "уу", "у-у", "у-у-у", "у-у-у-у", "ы", "ыы", "ыыы", "ыыыы", "ы-ы",
        // мысль, размышление
        "мм", "ммм", "м-м", "м-м-м", "мммм", "ммммм", "хм", "х-м", "хмм", "хммм",
        "эм", "эмм", "э-э", "э-э-э", "эге-гей", "и-и", "х-х",
        // согласие и понимание
        "угу", "угу-угу", "ага", "ага-ага", "ого", "ой", "уау", "а-у", "уа-у", "а-и",
        // просьба тишины и раздражение
        "ти", "тсс", "тш", "шш", "пф", "пфф", "пфс",
        // резкий испуг
        "бам", "бум", "бух", "бах", "ай", "аааа", "ой-ой",
    )

    /** Знаки, которые приклеиваются к междометию и не должны отделяться. */
    private val TAIL_PUNCT = "!?.,…"

    /** Что за звук задан ремаркой, или null. */
    fun soundOf(remark: String): Sound? {
        val low = remark.lowercase()
        return SOUNDS.firstOrNull { s -> s.words.any { low.contains(it) } }
    }

    /** Какое состояние описано в ремарке, или null. */
    fun stateOf(remark: String): State? {
        val low = remark.lowercase()
        return STATES.firstOrNull { s -> s.words.any { low.contains(it) } }
    }

    /**
     * Является ли токен междометием.
     *
     * Хвостовая пунктуация не мешает: «Ааа!», «ах…» — это то же самое
     * междометие, просто с восклицательным знаком. Без этого `*Ааа!*` и `[Ааа!]`
     * молчали: в наборе лежит «Ааа», а проверяли мы «Ааа!».
     */
    fun isInterjection(token: String): Boolean =
        token.lowercase().trimEnd(' ', '!', '?', '.', ',', ';', ':', '…', '‼', '⁇') in INTERJECTIONS

    /**
     * Подставляет вместо ремарок произносимое: звук → вытянутое междометие,
     * состояние и неизвестная ремарка → пусто (состояние меняет подачу, а не
     * текст; неизвестное не читается словом). Голое междометие в скобках
     * остаётся: `[ааа]` — это и есть звук, терять его незачем.
     */
    fun render(text: String): String {
        var out = CUE_SPAN.replace(text) { match ->
            val remark = match.groupValues[1].trim('*').trim()
            soundOf(remark)?.spoken
                ?: if (isInterjection(remark)) remark
                // `*курсив*` — текст, который нужно показать и прочесть, а не
                // указание говорящему. Согласуется с deliveries().
                else if (match.value.trimStart().startsWith("*") && stateOf(remark) == null) {
                    remark.replace(Regex("[*~]"), " ")
                } else ""
        }
        out = out.replace(Regex("[*~]"), " ")
        out = out.replace(Regex(""" {2,}"""), " ")
        return out.replace(Regex("""\s+([,.!?;:…])"""), "$1").trim()
    }

    /** Слова согласия и понимания — ровный тон, без испуга. */
    // «уа» убрано намеренно: это сленговое «назад», а не междометие.
    private val AGREEMENT = setOf("ага", "ага-ага", "угу", "угу-угу", "ого", "уау", "а-у", "а-у-а")

    /** Звуки размышления — тише и медленнее, реплика «потом». */
    private val THINKING = setOf(
        "мм", "ммм", "мммм", "ммммм", "м-м", "м-м-м", "хм", "х-м", "хмм", "хммм",
        "х-х", "эм", "эмм", "э-э", "э-э-э", "эге-гей", "и-и", "у", "уу", "у-у", "у-у-у",
        "у-у-у-у", "ы", "ыы", "ыыы", "ыыыы", "ы-ы", "ти", "тш", "шш",
    )

    /** Резкий испуг — короткий и высокий. */
    private val STARTLE = setOf("ой", "ой-ой", "ай", "бам", "бум", "бух", "бах")

    /**
     * Подача междометия по его виду и длине. Одно «а» — удивление, «аа» —
     * попытка закричать, «ааа» и длиннее — крик; раньше они читались
     * одинаково, и разница терялась.
     */
    fun interjectionDelivery(word: String): Delivery {
        // Синтезу регистр безразличен, но единый вид удобнее в логах и в
        // разметке: `ааа` из ремарки и в начале фразы выглядит одинаково.
        val spoken = word.replaceFirstChar { it.uppercaseChar() }
        val core = spoken.trim().lowercase().trim(*TAIL_PUNCT.toCharArray())
        val letters = core.filter { it.isLetter() }
        val aCount = letters.count { it == 'а' || it == 'a' }
        val breath = core.any { it == 'х' || it == 'ц' || it == 'h' }
        val sigh = core.any { it == 'у' || it == 'о' || it == 'ы' || it == 'y' }
        val long = letters.length >= 4
        val (p, r, pause) = when {
            core in AGREEMENT -> Triple(1.04f, 0.98f, 200)
            core in THINKING -> Triple(0.96f, 0.86f, 240)
            core in STARTLE -> Triple(1.18f, 1.06f, 220)
            breath -> Triple(1.06f, 0.92f, 240)
            sigh -> Triple(0.88f, 0.84f, 260)
            aCount >= 3 || long -> Triple(1.28f, 1.12f, 320)
            aCount == 2 -> Triple(1.16f, 0.90f, 240)
            else -> Triple(1.10f, 0.95f, 180)
        }
        return Delivery(spoken, pitch = p, rate = r, pauseAfterMs = pause, fromCue = true)
    }

    /**
     * Полная разметка реплики: куски со своей подачей.
     *
     * Ремарки убираются (звук превращается в произносимое с собственным
     * голосом), состояние становится множителем подачи, а голые междометия
     * выделяются отдельными кусками. Именно так «ааа» перестаёт читаться
     * вместе со следующей фразой общим тоном, а шёпот делает тише и
     * медленнее всю реплику.
     */
    fun deliveries(sentence: String): List<Delivery> {
        if (sentence.isBlank()) return emptyList()

        val spans = CUE_SPAN.findAll(sentence).toList()

        // Состояние: при нескольких ремарках побеждает самое заметное
        // (самая крайняя скорость), чтобы «(устал) (бегом)» не усреднялось.
        val state = spans.mapNotNull { stateOf(it.groupValues[1]) }
            .maxByOrNull { kotlin.math.abs(it.rate - 1f) }
        val sp = state?.pitch ?: 1.0f
        val sr = state?.rate ?: 1.0f

        val out = mutableListOf<Delivery>()

        /** Раскладывает обычный текст: голые междометия — отдельными кусками. */
        fun plain(raw: String) {
            // Осиротевшие `*` и `~` от незакрытой разметки не произносятся
            // и не превращаются в отдельный вызов движка.
            val part = raw.replace(Regex("[*~]"), " ")
            var last = 0
            CANDIDATE.findAll(part).forEach { m ->
                if (!isInterjection(m.value)) return@forEach
                // Знаки после междометия («А-а-а!») остаются с ним же, иначе
                // восклицательный знак уедет в отдельный кусок.
                var end = m.range.last + 1
                while (end < part.length && part[end] in TAIL_PUNCT) end++
                val head = part.substring(last, m.range.first).trim()
                if (isAudible(head)) out += Delivery(head, sp, sr, defaultPause(head))
                val d = interjectionDelivery(part.substring(m.range.first, end))
                if (isAudible(d.text)) {
                    out += Delivery(
                        d.text,
                        d.pitch * sp,
                        d.rate * sr,
                        d.pauseAfterMs,
                        fromCue = true,
                    )
                }
                last = end
            }
            val tail = part.substring(last).trim()
            if (isAudible(tail)) out += Delivery(tail, sp, sr, defaultPause(tail))
        }

        var cursor = 0
        for (span in spans) {
            plain(sentence.substring(cursor, span.range.first))
            cursor = span.range.last + 1
            val remark = span.groupValues[1].trim('*').trim()
            val sound = soundOf(remark)
            // `*курсив*` — обычный текст, а не ремарка. Молча выбрасывать слово
            // нельзя: OCR вебтунов и переводов даёт звёздочки сплошь и рядом.
            val starEmphasis = span.value.trimStart().startsWith("*") &&
                sound == null && stateOf(remark) == null && !isInterjection(remark)
            when {
                // Звук произносится сразу, собственным голосом: так вздох
                // отличается от крика, а не читается тем же тоном, что весь
                // текст под ним.
                sound != null -> out += Delivery(
                    sound.spoken,
                    sound.pitch * sp,
                    sound.rate * sr,
                    sound.pauseMs,
                    fromCue = true,
                    isSound = true,
                    soundId = sound.id,
                )
                isInterjection(remark) -> plain(remark)
                // Звёздочки вокруг обычного слова — выделение, а не указание
                // говорящему: произносим само слово.
                starEmphasis -> plain(span.value)
                // Состояние и неизвестная ремарка не произносятся: первое уже
                // учтено множителем, второе не должно читаться как слово.
                else -> Unit
            }
        }
        plain(sentence.substring(cursor))

        if (out.isEmpty()) {
            val clean = render(sentence)
            if (isAudible(clean)) out += Delivery(clean, sp, sr, defaultPause(clean))
        }
        return out
    }

    /**
     * Произносим ли кусок: хотя бы одна буква или цифра. Одинокая пунктуация
     * (`(` или `)` от незакрытой `(*ремарка*)`) не должна уходить в движок
     * отдельным вызовом — он её либо пропустит, либо озвучит как символы.
     */
    internal fun isAudible(text: String): Boolean = text.any { it.isLetterOrDigit() }

    /** Пауза после куска: та же логика, что в движке, но по самому куску. */
    private fun defaultPause(text: String): Int = when {
        text.endsWith("!") || text.endsWith("?") ||
            text.endsWith("‼") || text.endsWith("⁇") -> 420
        text.endsWith(",") || text.endsWith(";") -> 160
        else -> 260
    }
}

package eu.kanade.tachiyomi.data.tts

import android.speech.tts.TextToSpeech
import android.speech.tts.Voice
import logcat.LogPriority
import tachiyomi.core.common.util.system.logcat
import java.util.Locale

enum class VoiceKind { FEMALE, MALE, TEEN, OTHER }

/**
 * Классификация системных голосов по полу и подбор голоса для реплики.
 *
 * Важно: у Google Speech Services (самый распространённый движок на Android)
 * голоса называются НЕ по именам, а кодами вида `ru-ru-x-dfc-local`,
 * `ru-ru-x-ruf-network`. Прежняя версия искала в имени «svetlana»/«dmitry»
 * (это стиль Яндекс/RHVoice), поэтому все Google-голоса попадали в OTHER,
 * и pick(FEMALE)/pick(MALE) возвращали один и тот же первый голос — из-за
 * этого «работал только один голос».
 *
 * Теперь классификация трёхступенчатая:
 * 1. [Voice.getFeatures] / имя содержит явный признак пола;
 * 2. таблица известных кодов Google (`dfc`, `ruf`, … — женские; `rud`, `rue`,
 *    … — мужские) — коды берутся из середины имени `xx-xx-x-CODE-local`;
 * 3. детерминированный запасной вариант: голоса сортируются и делятся между
 *    полами по индексу, чтобы разные роли всё равно звучали по-разному.
 */
object VoiceHelper {
    private val femaleHints = listOf(
        "female", "woman", "svetlana", "milena", "oksana", "irina", "jane", "ksenia",
        "alena", "yelena", "elena", "anna", "arina", "maria", "natalia", "natalya",
        "tatiana", "tatyana", "victoria", "lyubov", "marianna", "жен", "женск", "девуш",
    )
    private val maleHints = listOf(
        "male", "man", "dmitry", "dmitri", "ermil", "filipp", "zahar", "pavel",
        "alexander", "aleksandr", "artemiy", "evgeniy", "mikhail", "vitaliy", "yuriy",
        "timofey", "seva", "anatol", "volodymyr", "maxim", "andrey", "ivan", "sergey", "муж",
    )
    private val teenHints = listOf("child", "kid", "teen", "young", "дет", "подрост", "umka")
    private val blacklist = listOf("locale", "default", "test")

    /**
     * Some OEM Android builds return an empty getVoices() set for RHVoice,
     * even though setVoice(name) and synthesis work. RHVoice validates a
     * manually constructed Voice by its name, so this catalog is used only as
     * a last-resort probe and only installed/enabled names are retained.
     */
    private val rhVoiceCatalog = mapOf(
        "ru" to listOf(
            "Aleksandr", "Aleksandr-hq", "Anna", "Arina", "Artemiy", "Elena",
            "Evgeniy-Rus", "Irina", "Mikhail", "Pavel", "Seva", "Tatiana",
            "Timofey", "Umka", "Victoria", "Vitaliy", "Yuriy",
        ),
        "en" to listOf("Alan", "BDL", "CLB", "Evgeniy-Eng", "Lyubov", "SLT"),
        "uk" to listOf("Anatol", "Marianna", "Natalia", "Volodymyr"),
    )

    private val languageAliases = mapOf(
        "ru" to setOf("ru", "rus"),
        "en" to setOf("en", "eng"),
        "ja" to setOf("ja", "jpn"),
        "ko" to setOf("ko", "kor"),
        "zh" to setOf("zh", "zho", "chi"),
        "uk" to setOf("uk", "ukr"),
    )

    /**
     * Коды голосов Google Speech Services. Имя выглядит как
     * `ru-ru-x-dfc-local`, значащая часть — предпоследний сегмент.
     */
    private val googleFemaleCodes = setOf(
        // ru
        "dfc", "ruf", "rug",
        // en
        "iob", "iog", "sfg", "tpc", "tpf", "jomn", "iol",
        // прочие распространённые
        "afb", "bfa", "cfa", "dfa", "dfb", "efa", "ffa", "gfa", "hfa", "sfb",
    )
    private val googleMaleCodes = setOf(
        // ru
        "rue", "rud", "dmc",
        // en
        "iom", "iog2", "tpd", "sfb2", "jomn2",
        // прочие распространённые
        "ama", "bma", "cma", "dma", "dmb", "ema", "fma", "gma", "hma", "smb",
    )

    fun russianVoices(tts: TextToSpeech?, enginePackage: String? = null): List<Voice> =
        voicesFor(tts, "ru", enginePackage)

    /** Ask a lazy TTS engine to load the requested language before getVoices(). */
    fun prepareForLanguage(tts: TextToSpeech?, language: String): Int {
        val engine = tts ?: return TextToSpeech.ERROR
        val locale = localeFor(language)
        runCatching { engine.isLanguageAvailable(locale) }
        return runCatching { engine.setLanguage(locale) }.getOrDefault(TextToSpeech.ERROR)
    }

    /**
     * Все голоса движка БЕЗ языкового фильтра.
     *
     * Нужно там, где жёсткий фильтр по языку оставляет пустой список: часть
     * OEM-движков не отдаёт ru-голоса, пока не докачан языковой пакет, и
     * `voicesFor(tts, "ru")` возвращает пусто при заведомо рабочем движке —
     * список в настройках выглядел пустым, а приложение требовало «установите
     * TTS-движок». [voicesFor] намеренно не меняется: он остаётся точным
     * выбором языка, а откат делает вызывающий UI.
     */
    fun allVoices(tts: TextToSpeech?, enginePackage: String? = null): List<Voice> {
        val engine = tts ?: return emptyList()
        val packageName = enginePackage?.takeIf { it.isNotBlank() }
            ?: runCatching { engine.defaultEngine }.getOrNull()
        val fromEngine = try {
            engine.voices.orEmpty()
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "voices() failed" }
            emptySet()
        }.filterNot { voice ->
            blacklist.any { blocked -> voice.name.equals(blocked, true) }
        }
        val isRhVoice = packageName.orEmpty().contains("rhvoice", ignoreCase = true)
        if (!isRhVoice) return fromEngine.sortedBy { it.name }
        // У RHVoice getVoices() часто пуст — доузнаём каталоги вручную.
        val probed = installedRhVoices(engine, "ru") +
            installedRhVoices(engine, "en") +
            installedRhVoices(engine, "uk")
        return (fromEngine + probed)
            .distinctBy { it.name.lowercase(Locale.US) }
            .sortedBy { it.name }
    }

    /** Языки, реально представленные в списке голосов (для переключателя). */
    fun languagesIn(voices: List<Voice>): List<String> =
        voices.asSequence()
            .mapNotNull { it.locale?.language?.lowercase(Locale.US)?.takeIf(String::isNotBlank) }
            .distinct()
            .sorted()
            .toList()

    /**
     * Голоса для языка [language] (ISO-639-1). Handles ISO-2/ISO-3 locale
     * differences, lazy engines and an RHVoice-specific OEM fallback.
     */
    fun voicesFor(
        tts: TextToSpeech?,
        language: String,
        enginePackage: String? = null,
    ): List<Voice> {
        val engine = tts ?: return emptyList()
        val packageName = enginePackage?.takeIf { it.isNotBlank() }
            ?: runCatching { engine.defaultEngine }.getOrNull()
        val isRhVoice = packageName.orEmpty().contains("rhvoice", ignoreCase = true)
        val all = try {
            engine.voices.orEmpty()
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "voices() failed" }
            emptySet()
        }
        val filtered = all.filter { voice ->
            languageMatches(voice.locale, language) &&
                blacklist.none { blocked -> voice.name.equals(blocked, true) }
        }.sortedBy { it.name }
        if (isRhVoice) {
            val direct = filtered.filterNot {
                it.name.equals("Russian", true) || it.name.equals("English", true)
            }
            if (direct.size > 1) return direct
            val probed = installedRhVoices(engine, language)
            val merged = (direct + probed)
                .distinctBy { it.name.lowercase(Locale.US) }
                .sortedBy { it.name }
            if (merged.isNotEmpty()) return merged
        }
        if (filtered.isNotEmpty()) return filtered

        // Some engines expose only the currently loaded/default Voice while
        // getVoices() is empty. Keep these as a generic one-voice fallback.
        return buildList {
            runCatching { engine.voice }.getOrNull()?.let(::add)
            runCatching { engine.defaultVoice }.getOrNull()?.let(::add)
        }.distinctBy { it.name }
            .filter { languageMatches(it.locale, language) }
            .sortedBy { it.name }
    }

    private fun localeFor(language: String): Locale = when (language.lowercase(Locale.US)) {
        "ru" -> Locale("ru", "RU")
        "en" -> Locale.US
        "ja" -> Locale.JAPAN
        "ko" -> Locale.KOREA
        "zh" -> Locale.SIMPLIFIED_CHINESE
        "uk" -> Locale("uk", "UA")
        else -> Locale(language)
    }

    private fun languageMatches(locale: Locale, language: String): Boolean {
        val requested = language.lowercase(Locale.US).substringBefore('-').substringBefore('_')
        val accepted = languageAliases[requested] ?: setOf(requested)
        val actual = buildSet {
            add(locale.language.lowercase(Locale.US))
            runCatching { locale.isO3Language.lowercase(Locale.US) }.getOrNull()?.let(::add)
        }
        return actual.any { it in accepted }
    }

    /**
     * RHVoice's service accepts a Voice by exact name and returns ERROR for a
     * missing/disabled pack. This lets us recover the installed subset on OEM
     * firmware where Android loses the service's onGetVoices() response.
     */
    /** Local RHVoice catalog used by the settings UI and loopback HTTP API. */
    fun localCatalog(language: String): List<Voice> {
        val lang = language.lowercase(Locale.US)
        val locale = localeFor(lang)
        return rhVoiceCatalog[lang].orEmpty().map { name ->
            Voice(
                name,
                locale,
                Voice.QUALITY_NORMAL,
                Voice.LATENCY_NORMAL,
                false,
                emptySet(),
            )
        }
    }

    private fun installedRhVoices(tts: TextToSpeech, language: String): List<Voice> {
        val candidates = localCatalog(language)
        if (candidates.isEmpty()) return emptyList()
        val original = runCatching { tts.voice }.getOrNull()
        val accepted = candidates.filter { candidate ->
            runCatching { tts.setVoice(candidate) == TextToSpeech.SUCCESS }.getOrDefault(false)
        }
        if (original != null) {
            runCatching { tts.setVoice(original) }
        } else {
            runCatching { tts.setLanguage(localeFor(language)) }
        }
        // Several OEM TextToSpeech clients reject manually constructed Voice
        // objects before RHVoice sees them. The same names still work when sent
        // as Engine.KEY_PARAM_VOICE_NAME with speak(), so keep the local list.
        return accepted.ifEmpty { candidates }
    }

    /** Значащий сегмент имени Google-голоса: `ru-ru-x-dfc-local` -> `dfc`. */
    private fun googleCode(name: String): String? {
        val parts = name.lowercase(Locale.US).split('-')
        val xIndex = parts.indexOf("x")
        return if (xIndex >= 0 && xIndex + 1 < parts.size) parts[xIndex + 1] else null
    }

    fun classify(v: Voice): VoiceKind {
        val n = (v.name + " " + v.locale?.toLanguageTag().orEmpty()).lowercase(Locale.US)

        // 1) признак пола, объявленный самим движком
        val features = runCatching { v.features }.getOrNull().orEmpty()
        features.forEach { f ->
            val lf = f.lowercase(Locale.US)
            if (lf.contains("female")) return VoiceKind.FEMALE
            if (lf.contains("male")) return VoiceKind.MALE
        }

        // 2) явные подсказки в имени (Яндекс, RHVoice, Samsung)
        when {
            teenHints.any { n.contains(it) } -> return VoiceKind.TEEN
            // "female" содержит "male", поэтому женское проверяем первым
            femaleHints.any { n.contains(it) } -> return VoiceKind.FEMALE
            maleHints.any { n.contains(it) } -> return VoiceKind.MALE
        }

        // 3) таблица кодов Google Speech Services
        googleCode(v.name)?.let { code ->
            if (code in googleFemaleCodes) return VoiceKind.FEMALE
            if (code in googleMaleCodes) return VoiceKind.MALE
        }

        return VoiceKind.OTHER
    }

    /**
     * Голос для роли. Если движок не даёт распознать пол (частый случай для
     * Google-кодов вне таблицы), голоса всё равно РАЗВОДЯТСЯ: женским ролям
     * достаётся первый нераспознанный, мужским — следующий. Так в сцене
     * звучат разные голоса, даже когда пол формально неизвестен.
     */
    fun pick(
        tts: TextToSpeech?,
        kind: VoiceKind,
        exactName: String?,
        enginePackage: String? = null,
    ): Voice? = pickFor(tts, kind, exactName, "ru", enginePackage)

    fun pickFor(
        tts: TextToSpeech?,
        kind: VoiceKind,
        exactName: String?,
        language: String,
        enginePackage: String? = null,
    ): Voice? {
        // Явно выбранный голос ищем по ВСЕМ голосам движка, а не только по
        // языковому фильтру: сетка показывает все языки, и локальный en-us
        // голос, выбранный пользователем, иначе всегда отбрасывался.
        if (!exactName.isNullOrBlank()) {
            tts?.voices.orEmpty().find { it.name == exactName }?.let { return it }
        }
        val all = voicesFor(tts, language, enginePackage)
        if (all.isEmpty()) return null

        // Локальные голоса предпочтительнее сетевых: работают без интернета.
        val ranked = all.sortedWith(compareBy({ it.isNetworkConnectionRequired }, { it.name }))
        val group = ranked.filter { classify(it) == kind }
        if (group.isNotEmpty()) {
            val preferred = when (kind) {
                VoiceKind.FEMALE -> group.firstOrNull { it.name.contains("svetlana", true) }
                VoiceKind.MALE -> group.firstOrNull { it.name.contains("dmitr", true) }
                else -> null
            }
            return preferred ?: group.first()
        }

        // Пол не определён — разводим роли по разным голосам детерминированно.
        val unknown = ranked.filter { classify(it) == VoiceKind.OTHER }
        val pool = unknown.ifEmpty { ranked }
        val index = when (kind) {
            VoiceKind.FEMALE -> 0
            VoiceKind.MALE -> 1
            VoiceKind.TEEN -> 2
            VoiceKind.OTHER -> 0
        }
        return pool.getOrNull(index % pool.size) ?: pool.firstOrNull()
    }

    /**
     * Отдельный голос на говорящего: разные персонажи одного пола получают
     * разные голоса из своей группы (по кругу), чтобы диалог не звучал
     * одинаково. [speakerSlot] — порядковый номер персонажа в сцене.
     */
    fun pickForSpeaker(
        tts: TextToSpeech?,
        kind: VoiceKind,
        speakerSlot: Int,
        language: String = "ru",
        enginePackage: String? = null,
    ): Voice? {
        val all = voicesFor(tts, language, enginePackage)
        if (all.isEmpty()) return null
        val ranked = all.sortedWith(compareBy({ it.isNetworkConnectionRequired }, { it.name }))
        val group = ranked.filter { classify(it) == kind }
        val pool = when {
            group.isNotEmpty() -> group
            else -> ranked.filter { classify(it) == VoiceKind.OTHER }.ifEmpty { ranked }
        }
        if (pool.isEmpty()) return null
        val offset = if (group.isEmpty()) {
            when (kind) {
                VoiceKind.MALE -> 1
                VoiceKind.TEEN -> 2
                else -> 0
            }
        } else {
            0
        }
        return pool[(offset + speakerSlot.coerceAtLeast(0)) % pool.size]
    }
}

/**
 * ЛОКАЛЬНЫЙ AI-помощник выбора голосов (по запросу пользователя: «внутренний
 * json АИ помогает с выбором голосов локально»). Никакой сети: правила в
 * JSON-файле /sdcard/Yomikai/AI/voice_rules.json, который можно править
 * руками или попросить AI-агента (write_file/edit_file). Формат:
 * {
 *   "rules": [
 *     {"contains": "имя_персонажа", "voice": "имя-голоса-или-id"},
 *     {"gender": "female", "engine": "onnx", "voice": "irina"}
 *   ]
 * }
 * recommend() применяет правила к тексту реплики и полу говорящего.
 */
object LocalVoiceAdvisor {

    data class Advice(val voiceName: String?, val onnxVoiceId: String?)

    private fun rulesFile(): java.io.File =
        java.io.File(
            android.os.Environment.getExternalStorageDirectory(),
            "Yomikai/AI/voice_rules.json",
        )

    fun recommend(text: String, gender: String?): Advice {
        val f = rulesFile()
        if (!f.isFile) return Advice(null, null)
        return runCatching {
            val root = org.json.JSONObject(f.readText())
            val rules = root.optJSONArray("rules") ?: return Advice(null, null)
            for (i in 0 until rules.length()) {
                val r = rules.optJSONObject(i) ?: continue
                val contains = r.optString("contains")
                val g = r.optString("gender")
                val matches =
                    (contains.isNotBlank() && text.contains(contains, ignoreCase = true)) ||
                        (contains.isBlank() && g.isNotBlank() && g == gender)
                if (matches) {
                    val voice = r.optString("voice")
                    return if (r.optString("engine") == "onnx") {
                        Advice(null, voice.ifBlank { null })
                    } else {
                        Advice(voice.ifBlank { null }, null)
                    }
                }
            }
            Advice(null, null)
        }.getOrDefault(Advice(null, null))
    }

    /** Есть ли файл правил (для подсказки в UI). */
    fun hasRules(): Boolean = rulesFile().isFile
}

package eu.kanade.tachiyomi.data.tts

import mihon.domain.ocr.service.OcrPreferences

/**
 * Правило интонации: узор текста → произношение этого предложения.
 *
 * Позволяет задать паузы и модификаторы питча/темпа для характерных фраз
 * («Что?!», шёпот, крик, внутренние монологи). Правило применяется к
 * КОНКРЕТНОМУ предложению (после деления текста на предложения), поэтому
 * ударение из всех правил словаря не «залипает» на всю реплику.
 *
 * [exact] = true — узор должен совпадать со всем предложением целиком
 * (без учёта регистра), иначе достаточно вхождения подстроки.
 */
data class VoiceIntonationRule(
    val pattern: String,
    val exact: Boolean = false,
    val pauseMs: Int = 0,
    val pitch: Float = 1.0f,
    val rate: Float = 1.0f,
    val enabled: Boolean = true,
) {
    fun matches(sentence: String): Boolean {
        if (!enabled || pattern.isBlank()) return false
        return if (exact) {
            sentence.equals(pattern.trim(), ignoreCase = true)
        } else {
            sentence.contains(pattern.trim(), ignoreCase = true)
        }
    }
}

/**
 * Доступ к словарю интонаций: JSON в настройках
 * ([OcrPreferences.voiceIntonations]). Первое подходящее правило выигрывает;
 * порядок в списке = приоритет.
 *
 * Где и как применяется (это объясняет, почему словарь раньше «не работал»
 * на части движков): системный движок режет реплику на предложения и ищет
 * правило для каждого предложения ([TtsSpeaker.speakSystem]), поэтому тон
 * меняется посередине реплики. Сетевые движки (Edge, удалённый сервер) озвучивают
 * реплику одним запросом — там правило ищется по всей реплике целиком, и
 * меняет темп/тон/паузу запроса. Google Web и ElevenLabs параметров просодии не
 * принимают вовсе, поэтому для них словарь недостижим.
 */
object VoiceIntonationDictionary {

    /**
     * Разбор строки JSON-массива правил. Ручной разбор (org.json в юнит-тестах
     * app-модуля не замокан) — см. [VoiceRoleDictionary.parse].
     */
    fun parse(json: String): List<VoiceIntonationRule> {
        val trimmed = json.trim()
        if (trimmed.isEmpty()) return emptyList()
        val objs = if (trimmed.startsWith("[")) {
            VoiceJson.parseObjects(trimmed)
        } else {
            VoiceJson.parseObject(trimmed).run { listOf(this) }
        }
        return objs.mapNotNull { obj ->
            val pattern = obj["pattern"].orEmpty().trim()
            if (pattern.isBlank()) return@mapNotNull null
            VoiceIntonationRule(
                pattern = pattern,
                exact = obj["exact"]?.equals("true", ignoreCase = true) == true,
                pauseMs = obj["pauseMs"]?.toIntOrNull()?.coerceIn(0, 10000) ?: 0,
                pitch = obj["pitch"]?.toFloatOrNull()?.takeIf { it > 0f } ?: 1.0f,
                rate = obj["rate"]?.toFloatOrNull()?.takeIf { it > 0f } ?: 1.0f,
                enabled = obj["enabled"]?.let { it != "false" } ?: true,
            )
        }
    }

    /** Ручная JSON-сериализация массива правил. */
    fun toJson(rules: List<VoiceIntonationRule>): String {
        val sb = StringBuilder("[")
        rules.forEachIndexed { idx, rule ->
            if (idx > 0) sb.append(',')
            sb.append('{')
            sb.append("\"pattern\":\"").append(VoiceJson.jsonEscape(rule.pattern)).append('"')
            sb.append(",\"exact\":").append(rule.exact)
            sb.append(",\"pauseMs\":").append(rule.pauseMs)
            sb.append(",\"pitch\":").append(rule.pitch)
            sb.append(",\"rate\":").append(rule.rate)
            sb.append(",\"enabled\":").append(rule.enabled)
            sb.append('}')
        }
        sb.append(']')
        return sb.toString()
    }

    fun load(prefs: OcrPreferences): List<VoiceIntonationRule> =
        parse(prefs.voiceIntonations().get())

    fun save(prefs: OcrPreferences, rules: List<VoiceIntonationRule>) {
        prefs.voiceIntonations().set(toJson(rules))
    }

    /** Первое правило, подошедшее под предложение, или null. */
    fun matchRule(rules: List<VoiceIntonationRule>, sentence: String): VoiceIntonationRule? =
        rules.firstOrNull { it.matches(sentence) }

    fun matchRule(prefs: OcrPreferences, sentence: String): VoiceIntonationRule? =
        matchRule(load(prefs), sentence)
}

