     internal enum class EngineType {
         CYRILLIC,
         MLKIT,
         LEGACY,
         FAST,
         GLENS,
         OWOCR,
         OPENROUTER,
         GOOGLE,
         ZEN_FREE,
     }

     private fun selectedEngineType(): EngineType = engineTypeOf(ocrModelPref.get())

