                 Row(modifier = Modifier.horizontalScroll(rememberScrollState())) {
                     listOf("full" to "Вся страница", "top" to "Верхняя половина", "bottom" to "Нижняя половина")
                         .forEach { (id, label) ->
                             FilterChip(
                                 selected = presetRegion == id,
