                             label = { Text(label) },
                             modifier = Modifier.padding(end = 6.dp),
                         )
                     }
                 }
                 Text(
                     if (contentType.id == "balanced") {
                         "Порядок выбирается тут и применяется к следующей странице «сверху вниз, колонками»."
                     } else {
