                                     "${pct}% — файл ${fileIndex + 1}/${files.size}",
                                     pct,
                                     downloadedBytes = totalDownloaded,
                                     totalBytes = totalPackSize.takeIf { it > 0 } ?: 0L,
+                                    notifId = notifIdFor(pack),
                                 )
                             }
