                     }
                 }
             } catch (e: Throwable) {
                 logcat(LogPriority.ERROR, e) { "OCR model pack download failed: $pack" }
                 false
             } finally {
                 downloadMutex.withLock { activePacks.remove(pack) }
                 setProgress(pack, null)
