         val streamFn = page?.stream ?: return

         try {
             val (source, isAnimated, cropRect) = withIOContext {
                 val source = streamFn().use { process(Buffer().readFrom(it)) }
                 val isAnimated = ImageUtil.isAnimatedAndSupported(source)
                 val cropRect = if (!isAnimated && viewer.config.imageCropBorders) {
                     ImageUtil.detectBorderCrop(source)
                 } else {
                     null
                 }
                 Triple(source, isAnimated, cropRect)
             }
             withUIContext {
                 frame.setFileCropRect(cropRect)
                 frame.setImage(
                     source,
                     isAnimated,
                     ReaderPageImageView.Config(
                         zoomDuration = viewer.config.doubleTapAnimDuration,
                         minimumScaleType = SubsamplingScaleImageView.SCALE_TYPE_FIT_WIDTH,
                         cropBorders = viewer.config.imageCropBorders,
                     ),
                 )
                 removeErrorLayout()
                 loadCachedOcrResult()
             }
         } catch (e: Throwable) {
             logcat(LogPriority.ERROR, e)
             withUIContext {
                 setError(e)
             }
         }
     }

     private fun process(imageSource: BufferedSource): BufferedSource {
         if (viewer.config.dualPageRotateToFit) {
             return rotateDualPage(imageSource)
         }

         if (viewer.config.dualPageSplit) {
             val isDoublePage = ImageUtil.isWideImage(imageSource)
             if (isDoublePage) {
                 val upperSide = if (viewer.config.dualPageInvert) ImageUtil.Side.LEFT else ImageUtil.Side.RIGHT
                 return ImageUtil.splitAndMerge(imageSource, upperSide)
             }
         }

         return imageSource
     }

     private fun rotateDualPage(imageSource: BufferedSource): BufferedSource {
         val isDoublePage = ImageUtil.isWideImage(imageSource)
         return if (isDoublePage) {
             val rotation = if (viewer.config.dualPageRotateToFitInvert) -90f else 90f
             ImageUtil.rotateImage(imageSource, rotation)
         } else {
             imageSource
         }
     }

     /**
      * Called when the page has an error.
      */
     private fun setError(error: Throwable?) {
         progressContainer.isVisible = false
         initErrorLayout(error)
         frame.setFileCropRect(null)
         frame.clearCachedOcrResult()
     }

     /**
      * Called when the image is decoded and going to be displayed.
      */
     private fun onImageDecoded() {
         progressContainer.isVisible = false
         removeErrorLayout()
     }

     private fun loadCachedOcrResult() {
         val currentPage = page ?: return frame.clearCachedOcrResult()
         val chapterId = currentPage.chapter.chapter.id ?: return frame.clearCachedOcrResult()
-        scope.launchIO {
+        // Задание запоминаем и отменяем при переиспользовании держателя:
+        // иначе результат подгрузки прилетал уже на другую страницу и
+        // подсвечивал области, которые к ней отношения не имеют.
+        cachedOcrJob?.cancel()
+        cachedOcrJob = scope.launchIO {
             val cachedResult = ocrRepository.getCachedPage(chapterId, currentPage.index)
             withUIContext {
                 frame.setCachedOcrResult(cachedResult)
                 viewer.activity.syncActiveOcrOverlay()
             }
         }
     }

     /**
      * Creates a new progress bar.
      */
     private fun createProgressIndicator(): ReaderProgressIndicator {
         progressContainer = FrameLayout(context)
         frame.addView(progressContainer, MATCH_PARENT, parentHeight)

         val progress = ReaderProgressIndicator(context).apply {
             updateLayoutParams<FrameLayout.LayoutParams> {
                 updateMargins(top = parentHeight / 4)
             }
         }
         progressContainer.addView(progress)
         return progress
     }

     /**
      * Initializes a button to retry pages.
      */
     private fun initErrorLayout(error: Throwable?): ReaderErrorBinding {
         if (errorLayout == null) {
             errorLayout = ReaderErrorBinding.inflate(LayoutInflater.from(context), frame, true)
             errorLayout?.root?.layoutParams = FrameLayout.LayoutParams(MATCH_PARENT, (parentHeight * 0.8).toInt())
             errorLayout?.actionRetry?.setOnClickListener {
                 page?.let { it.chapter.pageLoader?.retryPage(it) }
             }
         }

         val imageUrl = page?.imageUrl
         errorLayout?.actionOpenInWebView?.isVisible = imageUrl != null
         if (imageUrl != null) {
             if (imageUrl.startsWith("http", true)) {
                 errorLayout?.actionOpenInWebView?.setOnClickListener {
                     val sourceId = viewer.activity.viewModel.manga?.source

                     val intent = WebViewActivity.newIntent(context, imageUrl, sourceId)
                     context.startActivity(intent)
                 }
             }
         }

         errorLayout?.errorMessage?.text = with(context) { error?.formattedMessage }
             ?: context.stringResource(MR.strings.decode_image_error)

         return errorLayout!!
     }

     /**
      * Removes the decode error layout from the holder, if found.
      */
     private fun removeErrorLayout() {
         errorLayout?.let {
             frame.removeView(it.root)
             errorLayout = null
         }
     }
 }

