val keystorePropertiesFile = rootProject.file("keystore.properties")

android {
    namespace = "eu.kanade.tachiyomi"
...
            // Собираем ОДИН APK под arm64-v8a: это все актуальные телефоны.
            // Раньше выходило шесть файлов (v7a/arm64/x86/x86_64/universal/foss,
            // до 202 МБ каждый) — долгая сборка и путаница, какой ставить.
            // Вернуть остальные ABI: SPLIT_ALL_ABI=true.
            val allAbi = System.getenv("SPLIT_ALL_ABI") == "true"
            isEnable = true
            isUniversalApk = allAbi
            reset()
            if (allAbi) {
                include("armeabi-v7a", "arm64-v8a", "x86", "x86_64")
            } else {
                include("arm64-v8a")
            }
        }
    }

    packaging {
        jniLibs {
            keepDebugSymbols += listOf(
                "libandroidx.graphics.path",
                "libarchive-jni",
                "libconscrypt_jni",
                "libimagedecoder",
                "libquickjs",
                "libsqlite3x",
            )
                .map { "**/$it.so" }
        }
        resources {
            excludes += setOf(
                "kotlin-tooling-metadata.json",
                "LICENSE.txt",
                "META-INF/**/*.properties",
                "META-INF/**/LICENSE.txt",
                "META-INF/*.properties",
                "META-INF/*.version",
                "META-INF/DEPENDENCIES",
                "META-INF/LICENSE",
                "META-INF/NOTICE",
                "META-INF/README.md",
            )
        }
    }

    dependenciesInfo {
        includeInApk = Config.includeDependencyInfo
        includeInBundle = Config.includeDependencyInfo
    }

    buildFeatures {
        viewBinding = true
        buildConfig = true
        aidl = true
    }

    lint {
        abortOnError = false
        checkReleaseBuilds = false
    }

    androidResources {
        noCompress.addAll(listOf("tflite", "bin"))
    }
}

kotlin {
    compilerOptions {
        freeCompilerArgs.addAll(
            "-opt-in=androidx.compose.animation.ExperimentalAnimationApi",
            "-opt-in=androidx.compose.animation.graphics.ExperimentalAnimationGraphicsApi",
            "-opt-in=androidx.compose.foundation.ExperimentalFoundationApi",
