@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ReaderSettingsScreen(
    preferences: ReaderPreferences = remember { Injekt.get() },
) {
    Scaffold(
        topBar = { ReaderSettingsBar(preferences) },
    ) { padding ->
        ReaderSettingsList(
            preferences = preferences,
            contentPadding = padding,
        )
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun ReaderSettingsBar(preferences: ReaderPreferences) {
    TopAppBar(
        title = { Text(stringResource(MR.strings.pref_category_reader)) },
        actions = {
            IconButton(
                onClick = { preferences.persistCurrent() },
            ) {
                Icon(
                    imageVector = Icons.Outlined.Save,
                    contentDescription = stringResource(MR.strings.reader_constructor_save),
                )
            }
            IconButton(
                onClick = { preferences.resetToDefaults() },
            ) {
                Icon(
                    imageVector = Icons.Outlined.Restore,
                    contentDescription = stringResource(MR.strings.reader_constructor_defaults),
                )
            }
        },
    )
}

@Composable
private fun ReaderSettingsList(
    preferences: ReaderPreferences,
    contentPadding: PaddingValues,
) {
    LazyColumn(
        modifier = Modifier.fillMaxSize(),
        contentPadding = PaddingValues(
            top = contentPadding.calculateTopPadding() + 8.dp,
            bottom = contentPadding.calculateBottomPadding() + 24.dp,
        ),
        verticalArrangement = Arrangement.spacedBy(2.dp),
    ) {
        item { ReadingModeGroup(preferences) }
        item { DisplayGroup(preferences) }
        item { EInkGroup(preferences) }
        item { ReadingGroup(preferences) }
        item { ColorFilterGroup(preferences) }
        item { ControlsGroup(preferences) }
    }
}

@Composable
private fun ReadingModeGroup(preferences: ReaderPreferences) {
    val mode by preferences.defaultReadingMode.collectAsState()
    val orientation by preferences.defaultOrientationType.collectAsState()

    item("group-reading-mode")
    SettingsChipRow(MR.strings.pref_viewer_type) {
        ReadingMode.entries.drop(1).forEach { entry ->
            FilterChip(
                selected = mode == entry.flagValue,
                onClick = { preferences.defaultReadingMode.set(entry.flagValue) },
                label = { Text(stringResource(entry.stringRes)) },
            )
        }
    }

    HeadingItem(stringResource(MR.strings.pref_rotation_type))
    SettingsChipRow(MR.strings.pref_rotation_type) {
        ReaderOrientation.entries.drop(1).forEach { entry ->
            FilterChip(
                selected = orientation == entry.flagValue,
                onClick = { preferences.defaultOrientationType.set(entry.flagValue) },
                label = { Text(stringResource(entry.stringRes)) },
            )
        }
    }
}

@Composable
private fun DisplayGroup(preferences: ReaderPreferences) {
    HeadingItem(stringResource(MR.strings.pref_category_display))
    item("group-display")
    CheckboxItem(stringResource(MR.strings.pref_fullscreen), preferences.fullscreen)
    CheckboxItem(stringResource(MR.strings.pref_keep_screen_on), preferences.keepScreenOn)
    CheckboxItem(stringResource(MR.strings.pref_show_page_number), preferences.showPageNumber)
    CheckboxItem(stringResource(MR.strings.pref_page_transitions), preferences.pageTransitions)

    val theme by preferences.readerTheme.collectAsState()
    val themes = remember {
        listOf(
            MR.strings.black_background to 1,
            MR.strings.gray_background to 2,
            MR.strings.white_background to 0,
            MR.strings.automatic_background to 3,
        )
    }
    SettingsChipRow(MR.strings.pref_reader_theme) {
        themes.forEach { (labelRes, value) ->
            FilterChip(
                selected = theme == value,
                onClick = { preferences.readerTheme.set(value) },
                label = { Text(stringResource(labelRes)) },
            )
        }
    }
}

@Composable
private fun EInkGroup(preferences: ReaderPreferences) {
    val flashOn by preferences.flashOnPageChange.collectAsState()
    val duration by preferences.flashDurationMillis.collectAsState()
    val interval by preferences.flashPageInterval.collectAsState()
    val flashColor by preferences.flashColor.collectAsState()

    HeadingItem("E-Ink")
    item("group-eink")
    CheckboxItem(stringResource(MR.strings.pref_flash_page), preferences.flashOnPageChange)

    SliderItem(
        value = duration / ReaderPreferences.MILLI_CONVERSION,
        valueRange = 1..15,
        label = stringResource(MR.strings.pref_flash_duration),
        onChange = { preferences.flashDurationMillis.set(it * ReaderPreferences.MILLI_CONVERSION) },
        valueString = stringResource(MR.strings.pref_flash_duration_summary, duration),
        enabled = flashOn,
    )
    SliderItem(
        value = interval,
        valueRange = 1..10,
        label = stringResource(MR.strings.pref_flash_page_interval),
        onChange = { preferences.flashPageInterval.set(it) },
        enabled = flashOn,
    )
    SettingsChipRow(MR.strings.pref_flash_with) {
        listOf(
            MR.strings.pref_flash_style_black to ReaderPreferences.FlashColor.BLACK,
            MR.strings.pref_flash_style_white to ReaderPreferences.FlashColor.WHITE,
            MR.strings.pref_flash_style_white_black to ReaderPreferences.FlashColor.WHITE_BLACK,
        ).forEach { (labelRes, value) ->
            FilterChip(
                selected = flashColor == value,
                onClick = { preferences.flashColor.set(value) },
                label = { Text(stringResource(labelRes)) },
            )
        }
    }
}

@Composable
