@Composable
private fun ColorFilterGroup(preferences: ReaderPreferences) {
    val customBrightness by preferences.customBrightness.collectAsState()
    val colorFilter by preferences.customBrightnessValue.collectAsState()
    val brightness by preferences.customBrightnessValue.collectAsState()

