+package app.yomikai.reader.app
+
+import android.content.Context
+import android.net.Uri
+import android.provider.DocumentsContract
+import mihon.core.archive.ArchiveReader
+import java.io.File
+import java.io.InputStream
+
+/**
+ * Страницы главы, полученные по одной ссылке.
+ *
+ * Всё, что приложение читалки умеет на этом шаге, — открыть то, что уже лежит
+ * на диске: папку с картинками, архив (cbz/zip) или одиночный файл. Сетевые
+ * источники остаются у встроенной читалки: чтобы читать их из отдельного
+ * приложения, пришлось бы перенести туда ещё и авторизацию источников.
+ */
+class ReaderPages(
+    val count: Int,
+    private val open: (Int) -> InputStream?,
+) {
+    fun openStream(index: Int): InputStream? = open(index)
+}
+
+/**
+ * Разбирает [uri] на страницы. Возвращает null, если это не похоже на
+ * читаемую главу: вызывающий покажет внятную ошибку, а не пустой экран.
+ */
+fun resolvePages(context: Context, uri: Uri): ReaderPages? {
+    val mime = runCatching { context.contentResolver.getType(uri) }.getOrNull()
+    val isDirectory = mime == DocumentsContract.Document.MIME_TYPE_DIR || isFileDirectory(uri)
+    return if (isDirectory) directoryPages(context, uri) else archiveOrImage(context, uri)
+}
+
+private fun isFileDirectory(uri: Uri): Boolean {
+    if (uri.scheme != SCHEME_FILE) return false
+    return runCatching { uri.path?.let { File(it).isDirectory } == true }.getOrDefault(false)
+}
+
+/**
+ * Список файлов каталога: у `content://` это запрос к провайдеру документов,
+ * у `file://` — обычный список файлов. Порядок натуральный, иначе страницы
+ * идут 1, 10, 2.
+ */
+private fun directoryPages(context: Context, uri: Uri): ReaderPages? {
+    val children = if (uri.scheme == SCHEME_FILE) {
+        uri.path
+            ?.let { File(it).listFiles() }
+            .orEmpty()
+            .filter { it.isFile }
+            .map { "" to it.name }
+    } else {
+        val treeUri = runCatching { DocumentsContract.buildDocumentUriUsingTree(uri, DocumentsContract.getTreeDocumentId(uri)) }
+            .getOrDefault(uri)
+        childDocuments(context, treeUri)
+    }
+
+    val images = children
+        .map { it.second }
+        .filter { name -> IMAGE_EXTENSIONS.any { name.endsWith(it, ignoreCase = true) } }
+        .sortedWith(::compareNaturalCaseInsensitive)
+    if (images.isEmpty()) return null
+
+    val treeUri = if (uri.scheme == SCHEME_FILE) {
+        uri
+    } else {
+        runCatching { DocumentsContract.buildDocumentUriUsingTree(uri, DocumentsContract.getTreeDocumentId(uri)) }
+            .getOrDefault(uri)
+    }
+
+    return ReaderPages(images.size) { index -> openChild(context, treeUri, images[index]) }
+}
+
+/** Содержимое одного файла каталога по его имени. */
+private fun openChild(context: Context, treeUri: Uri, name: String): InputStream? {
+    val documentId = childDocuments(context, treeUri)
+        .firstOrNull { it.second == name }
+        ?.first
+    val childUri = if (documentId.isNullOrEmpty()) {
+        treeUri
+    } else {
+        runCatching { DocumentsContract.buildDocumentUriUsingTree(treeUri, documentId) }.getOrDefault(treeUri)
+    }
+    return runCatching { context.contentResolver.openInputStream(childUri) }.getOrNull()
+}
+
+/** Дети документа: id и имя. Имя нужно, чтобы отсортировать страницы. */
+private fun childDocuments(context: Context, treeUri: Uri): List<Pair<String, String>> {
+    val childrenUri = runCatching {
+        DocumentsContract.buildChildDocumentsUriUsingTree(treeUri, DocumentsContract.getTreeDocumentId(treeUri))
+    }.getOrNull() ?: return emptyList()
+
+    val result = mutableListOf<Pair<String, String>>()
+    runCatching {
+        context.contentResolver.query(childrenUri, null, null, null, null)?.use { cursor ->
+            val idColumn = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_DOCUMENT_ID)
+            val nameColumn = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_DISPLAY_NAME)
+            while (cursor.moveToNext()) {
+                val name = if (nameColumn >= 0) cursor.getString(nameColumn) else null
+                if (name != null) {
+                    val id = if (idColumn >= 0) cursor.getString(idColumn).orEmpty() else ""
+                    result += id to name
+                }
+            }
+        }
+    }
+    return result
+}
+
+/** Архив (cbz/zip) или одиночный файл. */
+private fun archiveOrImage(context: Context, uri: Uri): ReaderPages? {
+    val extension = uri.lastPathSegment?.substringAfterLast('.', "")?.lowercase().orEmpty()
+    if (extension !in ARCHIVE_EXTENSIONS) {
+        val single = runCatching { context.contentResolver.openInputStream(uri) }.getOrNull() ?: return null
+        single.close()
+        return ReaderPages(1) { runCatching { context.contentResolver.openInputStream(uri) }.getOrNull() }
+    }
+
+    val entries = runCatching {
+        context.contentResolver.openFileDescriptor(uri, "r")?.use { descriptor ->
+            ArchiveReader(descriptor).use { archive ->
+                archive.useEntries { sequence ->
+                    sequence
+                        .map { it.name }
+                        .filter { name -> IMAGE_EXTENSIONS.any { name.endsWith(it, ignoreCase = true) } }
+                        .sortedWith(::compareNaturalCaseInsensitive)
+                        .toList()
+                }
+            }
+        }
+    }.getOrNull().orEmpty()
+
+    if (entries.isEmpty()) return null
+
+    return ReaderPages(entries.size) { index ->
+        runCatching {
+            context.contentResolver.openFileDescriptor(uri, "r")?.use { descriptor ->
+                ArchiveReader(descriptor).use { it.getInputStream(entries[index]) }
+            }
+        }.getOrNull()
+    }
+}
+
+/** Сравнение как в проводнике: `2` раньше `10`, регистр не важен. */
+internal fun compareNaturalCaseInsensitive(a: String, b: String): Int {
+    val first = a.split(*SEPARATORS)
+    val second = b.split(*SEPARATORS)
+    for (i in 0 until minOf(first.size, second.size)) {
+        val left = first[i]
+        val right = second[i]
+        val leftNumber = left.toIntOrNull()
+        val rightNumber = right.toIntOrNull()
+        val result = when {
+            leftNumber != null && rightNumber != null -> leftNumber.compareTo(rightNumber)
+            leftNumber != null -> -1
+            rightNumber != null -> 1
+            else -> left.compareTo(right, ignoreCase = true)
+        }
+        if (result != 0) return result
+    }
+    return first.size.compareTo(second.size)
+}
+
+private const val SCHEME_FILE = "file"
+
+private val SEPARATORS = charArrayOf('.', '_', '-', ' ')
+
+private val IMAGE_EXTENSIONS = listOf(".jpg", ".jpeg", ".png", ".webp", ".gif", ".bmp", ".avif")
+
+private val ARCHIVE_EXTENSIONS = setOf("zip", "cbz", "cb7", "cbt")

