@@ -1,170 +1,228 @@
 package app.yomikai.reader.app

 import android.content.Context
 import android.net.Uri
 import android.provider.DocumentsContract
 import mihon.core.archive.ArchiveReader
 import java.io.File
 import java.io.InputStream

 /**
+ * Ссылка, выданная провайдером файлов Yomikai.
+ *
+ * Отличается от ссылки SAF тем, что это не дерево документов: каталог
+ * перечисляется запросом к самой ссылке, а у каждого ребёнка провайдер
+ * отдаёт готовую ссылку. Угадывать путь по имени нельзя — провайдер проверяет,
+ * что файл лежит внутри каталога приложения.
+ */
+private const val PROVIDER_SUFFIX = ".reader.files"
+private const val COLUMN_CHILD_URI = "reader_child_uri"
+
+/**
  * Страницы главы, полученные по одной ссылке.
  *
  * Всё, что приложение читалки умеет на этом шаге, — открыть то, что уже лежит
  * на диске: папку с картинками, архив (cbz/zip) или одиночный файл. Сетевые
  * источники остаются у встроенной читалки: чтобы читать их из отдельного
  * приложения, пришлось бы перенести туда ещё и авторизацию источников.
  */
 class ReaderPages(
     val count: Int,
     private val open: (Int) -> InputStream?,
 ) {
     fun openStream(index: Int): InputStream? = open(index)
 }

 /**
  * Разбирает [uri] на страницы. Возвращает null, если это не похоже на
  * читаемую главу: вызывающий покажет внятную ошибку, а не пустой экран.
  */
 fun resolvePages(context: Context, uri: Uri): ReaderPages? {
+    if (uri.authority?.endsWith(PROVIDER_SUFFIX) == true) {
+        return providerPages(context, uri)
+    }
     val mime = runCatching { context.contentResolver.getType(uri) }.getOrNull()
     val isDirectory = mime == DocumentsContract.Document.MIME_TYPE_DIR || isFileDirectory(uri)
     return if (isDirectory) directoryPages(context, uri) else archiveOrImage(context, uri)
 }

+/**
+ * Страницы по ссылке провайдера Yomikai: каталог — запросом с именем и
+ * готовыми ссылками детей, архив — так же, как обычный cbz.
+ */
+private fun providerPages(context: Context, uri: Uri): ReaderPages? {
+    val children = queryProviderChildren(context, uri)
+    if (children.isEmpty()) return archiveOrImage(context, uri)
+
+    val images = children
+        .filter { (_, name) -> IMAGE_EXTENSIONS.any { name.endsWith(it, ignoreCase = true) } }
+        .map { it.second }
+        .sortedWith(::compareNaturalCaseInsensitive)
+    if (images.isEmpty()) return null
+
+    val byName = children.associate { it.second to it.first }
+    return ReaderPages(images.size) { index ->
+        val childUri = byName[images[index]] ?: return@ReaderPages null
+        runCatching { context.contentResolver.openInputStream(Uri.parse(childUri)) }.getOrNull()
+    }
+}
+
+/** Дети каталога провайдера: ссылка и имя. */
+private fun queryProviderChildren(context: Context, uri: Uri): List<Pair<String, String>> {
+    val result = mutableListOf<Pair<String, String>>()
+    runCatching {
+        context.contentResolver.query(
+            uri,
+            arrayOf(DocumentsContract.Document.COLUMN_DISPLAY_NAME, COLUMN_CHILD_URI),
+            null,
+            null,
+            null,
+        )?.use { cursor ->
+            val nameColumn = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_DISPLAY_NAME)
+            val uriColumn = cursor.getColumnIndex(COLUMN_CHILD_URI)
+            while (cursor.moveToNext()) {
+                val name = if (nameColumn >= 0) cursor.getString(nameColumn) else null
+                val childUri = if (uriColumn >= 0) cursor.getString(uriColumn) else null
+                if (name != null && childUri != null) result += childUri to name
+            }
+        }
+    }
+    return result
