                         ScanFormatRow("TXT", "txt", scanFormat) { scanFormat = it }
                         ScanFormatRow("PDF", "pdf", scanFormat) { scanFormat = it }
                         ScanFormatRow("DOCX", "docx", scanFormat) { scanFormat = it }
                     }
